package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters"}) @AutoConfigureMockMvc class PublicCommunityQuestionHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean PublicCommunityQuestions service;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);return Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("jti","session").claim("subject_type",t.equals("op")?"operator_account":t.equals("owner")?"user":"staff_account").claim("role",t.equals("op")?"OPERATOR":t.equals("owner")?"OWNER":"MERCHANT").claim("app_id","operator-account").expiresAt(Instant.now().plusSeconds(600)).build();});}
 String body(){return "{\"question_message_id\":1,\"answer_message_id\":2,\"preview_hash\":\""+"a".repeat(64)+"\",\"consent_version\":\"R8C_PUBLIC_QA_V1\",\"consent\":true}";}
 @Test void rolesAndExactPublicSelectorsDenyBeforeDatabase()throws Exception{mvc.perform(get("/api/community/questions?vehicle_id=1")).andExpect(status().isUnauthorized());mvc.perform(get("/api/community/questions?vehicle_id=1").header("Authorization","Bearer op")).andExpect(status().isForbidden());mvc.perform(get("/api/admin/community/question-publications").header("Authorization","Bearer owner")).andExpect(status().isForbidden());for(String q:List.of("","vehicle_id=0","vehicle_id=1&vehicle_id=2","vehicle_id=1&owner_id=2","vehicle_id=1&cursor=0","vehicle_id=1&cursor=2&cursor=3","vehicle_id=1&page=1"))mvc.perform(get("/api/community/questions?"+q).header("Authorization","Bearer owner")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void independentConsentNoRawTextAndUuidKeyRequired()throws Exception{for(String b:List.of("{}",body()+"{}",body().replace("\"consent\":true","\"consent\":false"),body().replace("\"question_message_id\":1","\"question_message_id\":1.0"),body().replace("\"question_message_id\":1","\"question_message_id\":1,\"public_text\":\"private\""),body().replace("\"question_message_id\":1","\"question_message_id\":1,\"question_message_id\":2"))){mvc.perform(post("/api/owner/community/questions/cases/1/publications").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());}mvc.perform(post("/api/owner/community/questions/cases/1/publications").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content(body())).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void previewIsReadOnlyNoStoreAndErrorsHidePrivateSource()throws Exception{when(service.preview(any(),eq(1L),any())).thenReturn(Map.of("preview_hash","a".repeat(64)));mvc.perform(post("/api/owner/community/questions/cases/1/publication-preview").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content("{\"question_message_id\":1,\"answer_message_id\":2}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.preview_hash").value("a".repeat(64))).andExpect(header().string("Cache-Control","no-store"));when(service.pending(any(),eq(1))).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL body"));mvc.perform(get("/api/admin/community/question-publications").header("Authorization","Bearer op")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value(50300)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("SQL"))));}
 @Test void reviewReasonAndCurrentRevisionAreStrict()throws Exception{for(String b:List.of("{\"expected_revision\":1,\"decision\":\"APPROVE\",\"reason_code\":\"PRIVACY\"}","{\"expected_revision\":0,\"decision\":\"REJECT\",\"reason_code\":\"PRIVACY\"}","{\"expected_revision\":1,\"decision\":\"REJECT\",\"reason_code\":\"OTHER\"}"))mvc.perform(post("/api/admin/community/question-publications/1/moderate").header("Authorization","Bearer op").header("Idempotency-Key",UUID.randomUUID().toString()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());verifyNoInteractions(service);}
}
